package com.stocksim.ui.screens;

import com.stocksim.service.TradingPlatform;
import com.stocksim.ui.components.RoundedPanel;
import com.stocksim.ui.components.Theme;
import com.stocksim.ui.components.Ui;
import javax.swing.DefaultListModel;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import java.awt.BorderLayout;

/** Shows market events generated by the local simulator. */
public class NewsScreen extends JPanel implements Refreshable {
    private final TradingPlatform platform;
    private final DefaultListModel<String> events = new DefaultListModel<>();
    public NewsScreen(TradingPlatform platform) {
        this.platform = platform;
        setLayout(new BorderLayout());
        JPanel page = Ui.page("Market activity", "Offline simulated events based on the local price engine. This is not external financial news.");
        RoundedPanel card = Ui.card("Latest simulator events");
        JList<String> list = new JList<>(events);
        list.setFont(Theme.BODY);
        card.add(new JScrollPane(list), BorderLayout.CENTER);
        page.add(card, BorderLayout.CENTER);
        add(page, BorderLayout.CENTER);
        refreshScreen();
    }
    @Override public void refreshScreen() {
        events.clear();
        for (String event : platform.getMarket().getEvents()) events.addElement(event);
        if (events.isEmpty()) events.addElement("Market engine is warming up. Simulated activity will appear here.");
    }
}
